	public static void main(Args _args)
    {
        Object object;

        NDXDataTransfersToD365Modules lNDXDataTransfersToD365Modules;
        str className = '';

        if(_args.parmEnumType() == enumNum(NDXDataTransfersToD365Modules))
        {
            lNDXDataTransfersToD365Modules = _args.parmEnum();
            className = enum2Symbol(enumNum(NDXDataTransfersToD365Modules), lNDXDataTransfersToD365Modules);

            DictClass dictClass = new DictClass(className2Id(className));
            object = dictClass.makeObject();

            if(dictClass != null)
            {
                dictClass.callObject('startTransfer', object, _args);
            }
        }
	}
